    local function autoGameAliveBoss()
        local ok, tagged = pcall(v12.GetTagged, v12, "BossTag")
        if not ok or type(tagged) ~= "table" then
            return nil
        end

        local _, _, myRoot = v35()

        local best
        local bestDistance = math.huge

        for _, taggedObj in ipairs(tagged) do
            local model

            if taggedObj:IsA("Model") then
                model = taggedObj
            elseif taggedObj.Parent and taggedObj.Parent:IsA("Model") then
                model = taggedObj.Parent
            end

            if model and v36(model) then
                local root = v37(model)
                if root then
                    local distance = myRoot
                        and (myRoot.Position - root.Position).Magnitude
                        or 0

                    if distance < bestDistance then
                        best = model
                        bestDistance = distance
                    end
                end
            end
        end

        return best
    end

    local function autoGameFindNumber(value, wanted, depth, seen)
        if depth > 3 then
            return nil
        end

        local valueType = type(value)
        if valueType ~= "table" then
            return nil
        end

        seen = seen or {}
        if seen[value] then
            return nil
        end
        seen[value] = true

        for key, child in pairs(value) do
            local keyLower = string.lower(tostring(key))

            if type(child) == "number" then
                for _, wantedKey in ipairs(wanted) do
                    if keyLower == wantedKey
                        or string.find(keyLower, wantedKey, 1, true) then
                        return child
                    end
                end
            end
        end

        for _, child in pairs(value) do
            if type(child) == "table" then
                local found = autoGameFindNumber(
                    child,
                    wanted,
                    depth + 1,
                    seen
                )
                if found ~= nil then
                    return found
                end
            end
        end

        return nil
    end

    local function autoGameWeaponScore(name, item)
        if type(item) ~= "table" then
            return -math.huge
        end

        local damage = autoGameFindNumber(
            item,
            {"damage", "attack", "power", "strength"},
            0
        ) or 0

        local tier = autoGameFindNumber(
            item,
            {"tier", "rarity", "grade"},
            0
        ) or 0

        local price = autoGameFindNumber(
            item,
            {"price", "cost", "wen"},
            0
        ) or 0

        -- Damage-like stats are strongest signal; tier and price are only
        -- fallbacks when the item module exposes no explicit damage field.
        return damage * 1000000 + tier * 10000 + price
    end

    local function autoGameBestOwnedWeapon()
        if not v19.WeaponOps or not v39.Items then
            return nil
