        local owned = v19.WeaponOps.ownedSet()
        local bestName
        local bestScore = -math.huge

        for name, item in pairs(v39.Items) do
            if type(name) == "string"
                and type(item) == "table"
                and owned[name]
                and not v19.WeaponOps.Hidden[name]
                and (item.HasCombat or item.CombatPreset or item.Breathing) then

                local score = autoGameWeaponScore(name, item)

                if score > bestScore then
                    bestScore = score
                    bestName = name
                end
            end
        end

        return bestName
    end

