        v19.AutoGame.TrainingPlayingAt = 0
        v19.AutoGame.TrainingLastRestart = 0
    end

    local function autoGameStartTraining(now)
        local modes = v19.AutoGame.TrainingModes or {}
        if #modes == 0
            or not v19.TrainOps
            or type(v19.TrainOps.start) ~= "function" then
            return false
        end

        local index =
            math.clamp(
                tonumber(v19.AutoGame.TrainingIndex) or 1,
                1,
                #modes
            )

        local flagName = modes[index]
        local mode =
            v19.TrainOps.modes
            and v19.TrainOps.modes[flagName]

        autoGameHardPauseFarm()
        autoGameStopAllTraining()
        task.wait(0.10)

        now = now or os.clock()

        v19.AutoGame.Phase = "TrainingSetup"
        v19.AutoGame.TrainingMode = flagName
        v19.AutoGame.TrainingRequestedAt = now
        v19.AutoGame.TrainingPlayingAt = 0
        v19.AutoGame.TrainingLastRestart = now

        -- Start the source script's training routine DIRECTLY. Do not depend on
        -- whether the Activities tab/toggle callback happens to be available.
        v19.Flags[flagName] = true

        if v19.Runtime
            and type(v19.Runtime.syncToggle) == "function" then
            pcall(v19.Runtime.syncToggle, flagName, true)
        end

        pcall(v19.TrainOps.start, flagName)

        autoGameSetStatus(
            "Training setup: "
                .. tostring((mode and mode.Label) or flagName)
        )

        return true
    end

    local function autoGameFinishTraining(now, reason)
        local modes = v19.AutoGame.TrainingModes or {}
        local finishedMode = v19.AutoGame.TrainingMode

        autoGameStopAllTraining()

        if #modes > 0 then
            v19.AutoGame.TrainingIndex =
                ((tonumber(v19.AutoGame.TrainingIndex) or 1) % #modes) + 1
        end

        v19.AutoGame.LastTrainingEnd = now or os.clock()
        v19.AutoGame.Phase = "Progress"

        task.wait(0.15)
        autoGameResumeQuesting()

        if reason and reason ~= "" then
            autoGameSetStatus(
                "Training finished: "
                    .. tostring(finishedMode or "activity")
                    .. " | "
                    .. tostring(reason)
            )
        end
    end

    local function autoGameTrainingDue(now)
        now = now or os.clock()

        if v19.AutoGame.LastTrainingEnd == 0 then
            -- Let quest progression establish itself before the first break.
            v19.AutoGame.LastTrainingEnd = now
            return false
        end

        return (now - v19.AutoGame.LastTrainingEnd)
            >= (tonumber(v19.AutoGame.TrainingInterval) or 75)
    end

    local function autoGameTrainingTick(now)
        local phase = v19.AutoGame.Phase
        if phase ~= "TrainingSetup" and phase ~= "Training" then
            return false
        end

        -- This is deliberately repeated every tick. Even if some old quest
        -- coroutine wakes up once, the farm flags stay off while training.
        autoGameHardPauseFarm()

        local flagName = v19.AutoGame.TrainingMode
        local mode =
            flagName
            and v19.TrainOps
            and v19.TrainOps.modes
            and v19.TrainOps.modes[flagName]

        if not flagName or not mode then
            autoGameFinishTraining(now, "invalid mode")
            return true
        end

        local status = tostring(v19.TrainStatus or "Starting")
        local statusLower = string.lower(status)

        -- Executor does not support this training system: skip this mode rather
        -- than teleporting forever.
        if string.find(statusLower, "executor lacks", 1, true) then
            autoGameFinishTraining(now, status)
            return true
        end

        -- The source TrainOps sets exactly "Playing <Label>" only after the
        -- station prompt succeeded and the actual minigame exists.
        if string.find(statusLower, "playing ", 1, true) == 1 then
            if (v19.AutoGame.TrainingPlayingAt or 0) <= 0 then
                v19.AutoGame.TrainingPlayingAt = now
                v19.AutoGame.Phase = "Training"
            end

            local played =
                now - (v19.AutoGame.TrainingPlayingAt or now)

            local duration =
                tonumber(v19.AutoGame.TrainingPlayDuration) or 45

            if played >= duration then
                autoGameFinishTraining(now, "completed")
                return true
            end

            autoGameSetStatus(
                string.format(
                    "Training: %s | playing %ds/%ds",
                    tostring(mode.Label or flagName),
                    math.floor(played),
                    math.floor(duration)
                )
            )

            return true
        end

        -- Still travelling/streaming/finding a station. This time does NOT
        -- count against TrainingPlayDuration.
        local requestedAt =
            v19.AutoGame.TrainingRequestedAt or now

        local setupAge = now - requestedAt
        local timeout =
            tonumber(v19.AutoGame.TrainingStartTimeout) or 40

        if setupAge >= timeout then
            autoGameFinishTraining(
                now,
                "could not start: " .. status
            )
            return true
        end

        -- If the internal training thread died unexpectedly, restart only that
        -- same mode while keeping quest movement paused.
        if v19.TrainActive ~= flagName
            and (
                now - (v19.AutoGame.TrainingLastRestart or 0)
            ) >= (tonumber(v19.AutoGame.TrainingRestartDelay) or 4) then

            v19.AutoGame.TrainingLastRestart = now
            v19.Flags[flagName] = true

            if v19.Runtime
                and type(v19.Runtime.syncToggle) == "function" then
                pcall(v19.Runtime.syncToggle, flagName, true)
            end

            pcall(v19.TrainOps.start, flagName)
        end

        autoGameSetStatus(
            string.format(
                "Training setup: %s | %s | %ds",
                tostring(mode.Label or flagName),
                status,
                math.floor(setupAge)
            )
        )

        return true
    end

    local function autoGamePlayerLevel()
        if v118 and type(v118.playerLevel) == "function" then
            local ok, level = pcall(v118.playerLevel)
            if ok then
                return tonumber(level) or 0
            end
        end
        return 0
    end

    local function autoGameTryBuyWeapon()
        if not v39.Items or not v19.WeaponOps then
            return false
        end

        local now = os.clock()

        if (now - (v19.AutoGame.LastWeaponBuy or 0)) < 30 then
            return false
        end

        local currentWen = autoGameCurrentWen()
        if not currentWen then
            return false
        end

        local level = autoGamePlayerLevel()
        local owned = v19.WeaponOps.ownedSet()

        local bestName
        local bestScore = -math.huge
        local bestPrice

        for name, item in pairs(v39.Items) do
            if type(name) == "string"
                and type(item) == "table"
                and not owned[name]
                and not v19.WeaponOps.Hidden[name]
                and (item.HasCombat or item.CombatPreset or item.Breathing) then

                local cooldownUntil =
                    v19.AutoGame.BuyCooldowns[name] or 0

                if now >= cooldownUntil then
                    local price = autoGameFindNumber(
                        item,
                        {"price", "cost", "wen"},
                        0
                    )

                    local requiredLevel = autoGameFindNumber(
                        item,
                        {
                            "requiredlevel",
                            "levelrequirement",
                            "minlevel",
                            "levelreq",
                        },
                        0
                    ) or 0

                    if price
                        and price > 0
                        and price <= currentWen
                        and requiredLevel <= level then

                        local score = autoGameWeaponScore(name, item)

                        if score > bestScore then
                            bestName = name
                            bestScore = score
                            bestPrice = price
                        end
                    end
                end
            end
        end

        if not bestName then
            return false
        end

        v19.AutoGame.LastWeaponBuy = now
        autoGameSetStatus(
            string.format(
                "Weapon upgrade: %s | %s Wen",
                bestName,
                tostring(math.floor(bestPrice or 0))
            )
        )

        -- The supplied script's own fishing shop logic interacts with the
        -- seller BEFORE sending PurchaseFromShop. Do the same for weapons
        -- whenever the Items table exposes NPC/Seller/Merchant metadata.
        local item = v39.Items and v39.Items[bestName]
        local sellerName = autoGameFindString(
            item,
            {"npc", "seller", "merchant", "shopnpc"},
            0
        )

        if sellerName and sellerName ~= "" then
            local npc = v90(sellerName, true)

            if npc then
                local position =
                    v19.GameOps
                    and v19.GameOps.verifiedWorldPosition
                    and v19.GameOps.verifiedWorldPosition(npc)

                if position then
                    pcall(v104, position, 3)
                    task.wait(0.25)
                end

                local prompt =
                    npc:FindFirstChildWhichIsA(
                        "ProximityPrompt",
                        true
                    )

                if prompt and prompt.Enabled then
                    pcall(v115, prompt)
                    task.wait(0.60)
                end
            end
        end

        local sendOk = pcall(function()
            v42("PurchaseFromShop", bestName, 1)
        end)

        if not sendOk then
            v19.AutoGame.BuyCooldowns[bestName] = now + 60
            return false
        end

        -- The source shop code confirms success by ownership, not by the
        -- remote wrapper's return value.
        for _ = 1, 20 do
            task.wait(0.15)

            local ownedAfter = v19.WeaponOps.ownedSet()
            if ownedAfter[bestName] then
                v19.AutoGame.LastOwnedWeapon = bestName
                return true
            end
        end

        v19.AutoGame.BuyCooldowns[bestName] = now + 90
        return false
    end

    local function autoGameApplyBestWeapon()
        local best = autoGameBestOwnedWeapon()
        if not best then
            return
        end

        if v19.AutoGame.LastOwnedWeapon ~= best then
            v19.AutoGame.LastOwnedWeapon = best
        end

        v19.WeaponOps.Farm = best
        v19.WeaponOps.Boss = best

        autoGameInput("FarmWeapon", best)
        autoGameInput("BossWeapon", best)

        if v19.Flags.AutoEquip ~= false then
            pcall(v19.WeaponOps.equip, best)
        end
    end

    local function autoGameCoreFlags()
        v19.Flags.AutoEquip = true

        autoGameToggle("AutoAttack", true)
        autoGameToggle("FarmNoclip", true)
        autoGameToggle("PauseLowHP", true)
        autoGameToggle("AutoHealPotion", true)
        autoGameToggle("AutoSkillTree", true)

        local training =
            v19.AutoGame.Phase == "TrainingSetup"
            or v19.AutoGame.Phase == "Training"

