    local function autoGameBossChoices()
        if not v19.BossOps
            or type(v19.BossOps.refreshChoices) ~= "function" then
            return {}
        end

        local ok, choices = pcall(v19.BossOps.refreshChoices)
        if not ok or type(choices) ~= "table" then
            return {}
        end

        local result = {}
        local seen = {}

        for _, name in ipairs(choices) do
            name = v25(name)
            local key = v26(name)

            if name ~= "" and not seen[key] then
                seen[key] = true
                table.insert(result, name)
            end
        end

        return result
    end

    local function autoGameStartBossRun()
        local level = autoGamePlayerLevel()
        local minLevel = tonumber(v19.AutoGame.BossMinLevel) or 45
        local race = autoGameRaceName()

        if level < minLevel then
            return false, "Boss phase waits for level " .. tostring(minLevel)
        end

        if race == "Human" or race == "Unknown" then
            return false, "Boss phase waits for race progression"
        end

        local bestWeapon = autoGameBestOwnedWeapon()
        if not bestWeapon or bestWeapon == "" then
            return false, "Boss phase waits for a combat weapon"
        end

        if not v19.BossOps
            or type(v19.BossOps.setQueue) ~= "function"
            or type(v19.BossOps.acquire) ~= "function" then
            return false, "Boss system unavailable"
        end

        local choices = autoGameBossChoices()

        if #choices == 0 then
            return false, "No bosses discovered yet"
        end

        -- A non-empty queue is important: the original BossOps.acquire()
        -- starts BossOps.scout() when queued bosses are not currently spawned.
        pcall(v19.BossOps.setQueue, choices)

        v19.AutoGame.Phase = "Boss"
        v19.AutoGame.BossSessionStarted = os.clock()
        v19.AutoGame.BossProbeStarted = os.clock()
        v19.AutoGame.LastBossSwitch = os.clock()

        autoGameToggle("AutoProgress", false)
        task.wait(0.12)
        autoGameToggle("AutoBoss", true)

        pcall(v19.BossOps.acquire, true)

        autoGameSetStatus(
            string.format(
                "Boss hunt | Lv.%d | queue %d",
                level,
                #choices
            )
        )

        return true
    end

    local function autoGameSwitchToProgress()
        local needsRepair =
            v19.AutoGame.Phase ~= "Progress"
            or v19.Flags.AutoFarm ~= true
            or v19.Flags.AutoFarmQuest ~= true
            or v19.Flags.AutoQuestProgression ~= true

        if needsRepair then
            v19.AutoGame.Phase = "Progress"
            autoGameStopAllTraining()
            autoGameResumeQuesting()

            autoGameSetStatus(
                string.format(
                    "Questing | Lv.%d | %s",
                    autoGamePlayerLevel(),
                    (v19.ProgressionQuestName ~= ""
                        and v19.ProgressionQuestName
                        or "finding best quest")
                )
            )
        end
    end

    local function autoGameSwitchToBoss(_boss)
