    local function autoGameDisable()
        autoGameStopAllTraining()
        v19.AutoGame.Phase = "Idle"
        autoGameRestore()
        v19.AutoGame.Snapshot = nil
        autoGameSetStatus("Disabled")
    end

    local function autoGameEnable()
        if not v19.AutoGame.Snapshot then
            v19.AutoGame.Snapshot = autoGameSnapshot()
        end

        v19.AutoGame.LastTrainingEnd = os.clock()
        v19.AutoGame.TrainingMode = nil
        v19.AutoGame.TrainingRequestedAt = 0
        v19.AutoGame.TrainingPlayingAt = 0
        v19.AutoGame.TrainingLastRestart = 0
        v19.AutoGame.TrainingIndex = 1

        autoGameCoreFlags()
        autoGameApplyBestWeapon()
        autoGameSwitchToProgress()
        autoGameSetStatus("Starting progression planner...")
    end

    v19.Runtime.liveLoop(1.0, function()
        if not v19.Flags.AutoGame then
            return
        end

        local now = os.clock()

        -- TRAINING OWNS MOVEMENT.
        -- Handle it before weapon shops, quests, bosses, loot or race logic.
        if v19.AutoGame.Phase == "TrainingSetup"
            or v19.AutoGame.Phase == "Training" then

            autoGameCoreFlags()
            autoGameTrainingTick(now)
            return
        end

        autoGameCoreFlags()

        local level = autoGamePlayerLevel()
        local race = autoGameRaceName()

        -- Equipment progression may teleport to a seller, so it is deliberately
        -- skipped while a training block owns character movement.
        if (now - (v19.AutoGame.LastWeaponCheck or 0)) >= 12 then
            v19.AutoGame.LastWeaponCheck = now

            local bought = autoGameTryBuyWeapon()
            if bought then
                task.wait(0.45)
            end

            autoGameApplyBestWeapon()
        end

        -- EARLY/MID GAME:
        -- Quest normally. At intervals, completely pause quest movement and
        -- run one training minigame until it has actually PLAYED long enough.
        local raceLevelGate = 45

        if level < raceLevelGate then
            autoGameToggle("AutoBoss", false)

            if autoGameTrainingDue(now) then
                if autoGameStartTraining(now) then
                    return
                end
            end

            autoGameSwitchToProgress()

            autoGameSetStatus(
                string.format(
                    "Building character | Lv.%d/45 | Quest -> real training -> Quest | Race: %s",
                    level,
                    tostring(race)
                )
            )

            return
        end

        -- At level 45, a Human account uses the source script's existing
        -- Slayer progression. Disable normal farming so its own objectives own
        -- movement and do not fight with quest teleporting.
        if race == "Human" then
            autoGameStopAllTraining()
            autoGameHardPauseFarm()

            if v19.Flags.AutoBecomeDemon then
                autoGameToggle("AutoBecomeDemon", false)
            end

            if not v19.Flags.AutoBecomeSlayer then
                autoGameToggle("AutoBecomeSlayer", true)
            end

            if (now - (v19.AutoGame.LastRaceDrive or 0)) >= 3 then
                v19.AutoGame.LastRaceDrive = now

                if v256 and type(v256.tryBecomeSlayer) == "function" then
                    task.spawn(v256.tryBecomeSlayer)
                end
            end

            v19.AutoGame.Phase = "Race"
            autoGameSetStatus(
                "Race progression | Auto Slayer | "
                    .. tostring(v19.RaceStatus or "working")
            )

            return
        end

        if v19.Flags.AutoBecomeSlayer then
            autoGameToggle("AutoBecomeSlayer", false)
        end

        if autoGameTrainingDue(now)
            and v19.AutoGame.Phase ~= "Boss" then

            if autoGameStartTraining(now) then
                return
            end
        end

        -- BOSS PHASE:
        -- level >= 45, race completed, combat weapon owned.
        if v19.AutoGame.Phase == "Boss" then
            local sessionAge =
                now - (v19.AutoGame.BossSessionStarted or now)

            local boss
            if v19.BossOps
                and type(v19.BossOps.acquire) == "function" then

                local ok, result =
                    pcall(v19.BossOps.acquire, false)

                if ok then
                    boss = result
                end
            end

            if boss and v36(boss) then
                autoGameSetStatus(
                    string.format(
                        "Boss fight: %s | Lv.%d | %s",
                        tostring(boss.Name),
                        level,
                        tostring(
                            autoGameBestOwnedWeapon()
                            or "weapon?"
                        )
                    )
                )

                if sessionAge
                    >= (tonumber(v19.AutoGame.BossSessionMax) or 120) then
                    autoGameSwitchToProgress()
                end

                return
            end

            if v19.BossOps
                and type(v19.BossOps.acquire) == "function" then
                pcall(v19.BossOps.acquire, true)
            end

            local searchAge =
                now - (v19.AutoGame.BossProbeStarted or now)

            autoGameSetStatus(
                string.format(
                    "Boss scouting | %s",
                    tostring(v19.BossStatus or "searching")
                )
            )

            if searchAge
                >= (tonumber(v19.AutoGame.BossSearchTimeout) or 35) then
                autoGameSwitchToProgress()
            end

            return
        end

        local minBossLevel =
            tonumber(v19.AutoGame.BossMinLevel) or 45

        local sinceBoss =
            now - (v19.AutoGame.LastBossSwitch or 0)

        local weaponReady =
            autoGameBestOwnedWeapon() ~= nil

        if level >= minBossLevel
            and race ~= "Human"
            and race ~= "Unknown"
            and weaponReady
            and sinceBoss
                >= (tonumber(v19.AutoGame.BossQuestInterval) or 180) then

            local started, reason =
                autoGameStartBossRun()

            if started then
                return
            end

            v19.AutoGame.LastBossSwitch =
                now
                - math.max(
                    (tonumber(v19.AutoGame.BossQuestInterval) or 180) - 20,
                    0
                )

            autoGameSetStatus(
                "Progressing | boss delayed: "
                    .. tostring(reason or "not ready")
            )
        end

        autoGameSwitchToProgress()

        autoGameSetStatus(
            string.format(
                "Progressing | Lv.%d | Race: %s | Weapon: %s | %s",
                level,
                tostring(race),
                tostring(autoGameBestOwnedWeapon() or "none"),
                (v19.ProgressionQuestName ~= ""
                    and v19.ProgressionQuestName
                    or "finding best quest")
            )
        )
    end)

